// DialectOS desktop half. Plain ESM for the Hermes desktop plugin SDK: no build
// step, imports only from the SDK and React. Data comes from the agent half's
// dashboard/plugin_api.py through ctx.rest, so the page runs the same CLI,
// settings and limits as the agent tools. Fonts: Chakra Petch (OFL) Latin subset
// and the r16 mark, embedded between the generated markers below.
import {
  Button, CopyButton, EmptyState, ErrorState, PALETTE_AREA, ROUTES_AREA, SIDEBAR_NAV_AREA,
  Skeleton, host, relativeTime, useQuery, useQueryClient
} from '@hermes/plugin-sdk'
import { useState } from 'react'
import { jsx, jsxs } from 'react/jsx-runtime'

const ID = 'dialectos'
const PATH = '/dialectos'
const FACE = 'DialectOS Chakra Petch'

// --- FONTS (generated) -------------------------------------------------------
const FONTS = {
  500: '',
  600: ''
}
// --- MARK (generated) --------------------------------------------------------
const MARK = ''
// --- end generated -----------------------------------------------------------

// Walnut light sand ground with Walnut ink; apatite teal from the mark is the one
// identity accent. Receipt: docs/DESIGN-PREFLIGHT.md §8. Every state has a label.
const CSS = `
${Object.entries(FONTS).map(([w, b]) => `@font-face{font-family:'${FACE}';font-style:normal;font-weight:${w};font-display:swap;src:url(data:font/woff;base64,${b}) format('woff')}`).join('\n')}
.dos-host{container-type:inline-size;width:100%;min-height:100vh;box-sizing:border-box;color-scheme:light;background:#f3ebdf;color:#3b342e;--ui-bg-primary:transparent;--ui-bg-editor:transparent;--ui-bg-secondary:#f8f1e7;--ui-bg-elevated:rgba(255,250,242,.55);--ui-bg-card:#fbf5ec;--ui-bg-tertiary:rgba(255,250,242,.35);--ui-bg-input:#fffaf2;--ui-control-hover-background:rgba(59,52,46,.07);--ui-control-active-background:rgba(59,52,46,.12);--ui-row-hover-background:rgba(59,52,46,.05);--ui-text-primary:#3b342e;--ui-text-secondary:#4a423a;--ui-text-tertiary:#5a5047;--ui-stroke-primary:rgba(59,52,46,.28);--ui-stroke-secondary:rgba(59,52,46,.20);--ui-stroke-tertiary:rgba(59,52,46,.14);--ui-stroke-quaternary:rgba(59,52,46,.08);--ui-accent:#1d5e66;--dos-id:#1d5e66;--dos-pass:#46622a;--dos-block:#8f3a33;--dos-adv:#6b5f54}
.dos{max-width:1120px;margin:0 auto;padding:28px 32px 48px;display:grid;gap:20px;font-family:var(--font-sans,system-ui,sans-serif);font-size:13px;line-height:1.45;color:var(--ui-text-primary);--dos-display:'${FACE}',var(--font-sans,system-ui,sans-serif)}
.dos *{box-sizing:border-box}
.dos-head{display:grid;grid-template-columns:48px minmax(0,1fr);gap:4px 14px;align-items:center;padding-bottom:16px;border-bottom:2px solid color-mix(in srgb,var(--dos-id) 55%,transparent)}
.dos-head img{width:48px;height:48px;grid-row:span 2}
.dos-title{margin:0;font-family:var(--dos-display);font-weight:600;font-size:22px;letter-spacing:.03em;line-height:1.1}
.dos-tag{margin:0;font-size:13px;color:var(--ui-text-secondary)}
.dos-facts{display:flex;flex-wrap:wrap;gap:8px}
.dos-fact{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border:1px solid var(--ui-stroke-tertiary);border-radius:13px;background:var(--ui-bg-card);font-size:12px;color:var(--ui-text-secondary)}
.dos-fact b{font-weight:600;color:var(--ui-text-primary)}
.dos-fact[data-off]{border-style:dashed}
.dos-note{display:block;margin:0;padding:10px 14px;border:1px solid var(--ui-stroke-secondary);border-left:3px solid var(--dos-adv);border-radius:8px;background:var(--ui-bg-elevated);font-size:12.5px;color:var(--ui-text-secondary)}
.dos-note b{color:var(--ui-text-primary)}
.dos-label{margin:0;font-family:var(--dos-display);font-weight:600;font-size:14px;letter-spacing:.02em}
.dos-sub{margin:2px 0 0;font-size:12px;color:var(--ui-text-tertiary)}
.dos-card{background:var(--ui-bg-card);border:1px solid var(--ui-stroke-tertiary);border-radius:10px;padding:16px;display:grid;gap:12px;min-width:0}
.dos-cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;align-items:start}
.dos-field{display:grid;gap:5px;font-size:12px;font-weight:500;color:var(--ui-text-secondary)}
.dos textarea,.dos select{font:inherit;font-size:13px;color:var(--ui-text-primary);background:var(--ui-bg-input);border:1px solid var(--ui-stroke-secondary);border-radius:6px;padding:8px 10px;width:100%}
.dos textarea{min-height:84px;resize:vertical;line-height:1.5}
.dos select{height:30px;padding:0 8px;width:auto;min-width:220px}
.dos textarea:focus-visible,.dos select:focus-visible,.dos button:focus-visible{outline:2px solid var(--dos-id);outline-offset:1px}
.dos-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.dos-why{font-size:12px;color:var(--ui-text-tertiary)}
.dos-out{border:1px solid var(--ui-stroke-tertiary);border-radius:8px;background:#fffaf2;padding:12px;display:grid;gap:8px}
.dos-out pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;font-size:13.5px;line-height:1.55;color:var(--ui-text-primary)}
.dos-verdict{display:inline-flex;align-items:center;gap:6px;height:24px;padding:0 9px;border-radius:12px;border:1px solid currentColor;font-size:12px;font-weight:600}
.dos-verdict[data-v=pass]{color:var(--dos-pass)}.dos-verdict[data-v=block]{color:var(--dos-block)}.dos-verdict[data-v=adv]{color:var(--dos-adv)}
.dos-verdict i{width:7px;height:7px;border-radius:50%;background:currentColor}
.dos-verdict[data-v=adv] i{background:transparent;border:1.5px solid currentColor}
.dos-issues{margin:0;padding-left:18px;display:grid;gap:3px;font-size:12.5px;color:var(--ui-text-secondary)}
.dos-issues b{color:var(--dos-block);font-weight:600;margin-right:4px}
.dos-err{font-size:12.5px;color:var(--dos-block)}
.dos-sum{display:grid;grid-template-columns:128px minmax(48px,1fr) 96px;white-space:nowrap;gap:10px;align-items:center;min-height:30px;border-top:1px solid var(--ui-stroke-quaternary);font-size:12.5px}
.dos-sum:first-of-type{border-top:0}
.dos-code{font-family:var(--font-mono,ui-monospace,monospace);font-size:12px;color:var(--ui-text-primary)}
.dos-bar{display:flex;height:8px;border-radius:4px;overflow:hidden;background:var(--ui-stroke-quaternary)}
.dos-bar i{display:block;height:100%}
.dos-num{text-align:right;font-variant-numeric:tabular-nums;color:var(--ui-text-secondary)}
.dos-ev{display:grid;grid-template-columns:80px minmax(0,1fr) 52px 76px;white-space:nowrap;gap:10px;align-items:center;min-height:30px;border-top:1px solid var(--ui-stroke-quaternary);font-size:12.5px;color:var(--ui-text-secondary)}
.dos-ev:first-of-type{border-top:0}
.dos-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:6px}
.dos-chip{all:unset;cursor:pointer;display:flex;gap:8px;align-items:baseline;padding:6px 9px;border:1px solid var(--ui-stroke-quaternary);border-radius:6px;font-size:12.5px;color:var(--ui-text-secondary)}
.dos-chip:hover{background:var(--ui-row-hover-background)}
.dos-chip[aria-pressed=true]{border-color:var(--dos-id);background:color-mix(in srgb,var(--dos-id) 8%,transparent);color:var(--ui-text-primary)}
.dos-chip:focus-visible{outline:2px solid var(--dos-id);outline-offset:1px}
.dos-chip small{margin-left:auto;font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ui-text-tertiary)}
@container (max-width:760px){.dos{padding:18px 16px 36px}.dos-cols{grid-template-columns:minmax(0,1fr)}.dos select{min-width:0;width:100%}.dos-ev{grid-template-columns:76px minmax(0,1fr) 46px 72px;gap:8px}.dos-ev>*{overflow:hidden;text-overflow:ellipsis}}
`

const PROVIDER_NAMES = { llm: 'LLM', deepl: 'DeepL', libre: 'LibreTranslate', mymemory: 'MyMemory' }
const TOOL_NAMES = { dialectos_translate: 'Translate', dialectos_detect: 'Detect', dialectos_validate: 'Check', dialectos_list_dialects: 'List' }

const post = (ctx, path, body) => ctx.rest(path, { method: 'POST', body })
const ago = ts => (ts ? relativeTime(ts * 1000) : '')

function Verdict({ check }) {
  if (!check) return null
  if (!check.ok && check.valid == null) return jsx('p', { className: 'dos-err', children: `Check could not run: ${check.error || 'unknown error'}` })
  const blocking = (check.issues || []).filter(i => i.blocking)
  const v = check.valid && !blocking.length ? 'pass' : blocking.length ? 'block' : 'adv'
  const label = v === 'pass' ? 'Passed the checks' : v === 'block' ? `${blocking.length} blocking issue${blocking.length === 1 ? '' : 's'}` : 'Did not pass'
  return jsxs('div', { style: { display: 'grid', gap: 8 }, children: [
    jsxs('div', { className: 'dos-row', children: [
      jsxs('span', { className: 'dos-verdict', 'data-v': v, children: [jsx('i', {}), label] }),
      jsx('span', { className: 'dos-why', children: `${check.dialect} · advisory, not proof of meaning` })
    ] }),
    (check.issues || []).length ? jsx('ul', { className: 'dos-issues', children: check.issues.slice(0, 8).map((i, n) =>
      jsxs('li', { children: [i.blocking ? jsx('b', { children: 'Blocking' }) : null, i.message] }, n)) }) : null
  ] })
}

function DialectSelect({ value, onChange, dialects, id }) {
  return jsx('select', { id, value, onChange: e => onChange(e.target.value), children: (dialects.length ? dialects : [{ code: value, name: '' }]).map(d =>
    jsx('option', { value: d.code, children: d.name ? `${d.code} · ${d.name}` : d.code }, d.code)) })
}

function TryIt({ ctx, status, dialects, target, setTarget, refresh }) {
  const [text, setText] = useState('')
  const [busy, setBusy] = useState('')
  const [out, setOut] = useState(null)
  const provider = status?.provider
  const run = async kind => {
    if (!text.trim()) return
    setBusy(kind); setOut(null)
    try {
      const res = await post(ctx, `/${kind}`, kind === 'translate' ? { text, dialect: target } : { text })
      setOut({ kind, res })
    } catch (e) {
      setOut({ kind, res: { ok: false, error: String(e?.message || e) } })
    } finally { setBusy(''); refresh() }
  }
  const r = out?.res
  const det = out?.kind === 'detect' && r?.ok ? r.data : null
  return jsxs('section', { className: 'dos-card', 'aria-labelledby': 'dos-try', children: [
    jsxs('div', { children: [jsx('h2', { id: 'dos-try', className: 'dos-label', children: 'Translate or detect' }),
      jsx('p', { className: 'dos-sub', children: 'Detect runs on this machine. Translate sends the text to your provider, then checks the result against your text.' })] }),
    jsxs('label', { className: 'dos-field', children: ['Text', jsx('textarea', { value: text, maxLength: status?.limits?.text || 8000, placeholder: 'Paste English to translate, or Spanish to detect its dialect.', onChange: e => setText(e.target.value) })] }),
    jsxs('div', { className: 'dos-row', children: [
      jsx('label', { htmlFor: 'dos-target', className: 'dos-why', children: 'Into' }),
      jsx(DialectSelect, { id: 'dos-target', value: target, onChange: setTarget, dialects }),
      jsx(Button, { size: 'sm', disabled: !provider || !text.trim() || !!busy, onClick: () => run('translate'), children: busy === 'translate' ? 'Translating…' : 'Translate' }),
      jsx(Button, { size: 'sm', variant: 'ghost', disabled: !text.trim() || !!busy, onClick: () => run('detect'), children: busy === 'detect' ? 'Detecting…' : 'Detect dialect' })
    ] }),
    !provider ? jsx('p', { className: 'dos-why', children: 'Translate is off until you name a provider (llm, deepl, libre or mymemory) in the plugin settings. Detect and checks work without one.' }) : null,
    r && !r.ok ? jsx('p', { className: 'dos-err', children: r.error || 'Something went wrong.' }) : null,
    out?.kind === 'translate' && r?.ok ? jsxs('div', { className: 'dos-out', children: [
      jsxs('div', { className: 'dos-row', style: { justifyContent: 'space-between' }, children: [
        jsx('span', { className: 'dos-why', children: `${r.dialect} via ${PROVIDER_NAMES[provider] || provider}` }),
        jsx(CopyButton, { text: r.text, label: 'Copy', buttonVariant: 'ghost', buttonSize: 'xs' })] }),
      jsx('pre', { children: r.text }),
      jsx(Verdict, { check: r.check })
    ] }) : null,
    det ? jsx('div', { className: 'dos-out', children: det.dialect
      ? jsxs('p', { style: { margin: 0 }, children: [jsx('b', { children: `Looks like ${det.dialect}` }), det.name ? ` · ${det.name}` : '',
          jsx('span', { className: 'dos-why', children: ` · confidence ${Math.round((det.confidence || 0) * 100)}%${det.isReliable === false ? ', low' : ''}${(det.matchedKeywords || []).length ? ` · markers: ${det.matchedKeywords.slice(0, 6).join(', ')}` : ''}` })] })
      : jsx('p', { style: { margin: 0 }, children: 'Not enough regional markers to name a dialect. Short or neutral Spanish often reads the same everywhere.' }) }) : null
  ] })
}

function CheckPair({ ctx, dialects, target, setTarget, refresh }) {
  const [source, setSource] = useState('')
  const [translated, setTranslated] = useState('')
  const [busy, setBusy] = useState(false)
  const [res, setRes] = useState(null)
  const run = async () => {
    setBusy(true); setRes(null)
    try { setRes(await post(ctx, '/validate', { source, translated, dialect: target })) }
    catch (e) { setRes({ ok: false, error: String(e?.message || e) }) }
    finally { setBusy(false); refresh() }
  }
  return jsxs('section', { className: 'dos-card', 'aria-labelledby': 'dos-check', children: [
    jsxs('div', { children: [jsx('h2', { id: 'dos-check', className: 'dos-label', children: 'Check a translation' }),
      jsx('p', { className: 'dos-sub', children: 'Runs on this machine. Checks placeholders, structure and regional terms against the source.' })] }),
    jsxs('label', { className: 'dos-field', children: ['Source', jsx('textarea', { value: source, maxLength: 8000, onChange: e => setSource(e.target.value) })] }),
    jsxs('label', { className: 'dos-field', children: ['Translation', jsx('textarea', { value: translated, maxLength: 100000, onChange: e => setTranslated(e.target.value) })] }),
    jsxs('div', { className: 'dos-row', children: [
      jsx(DialectSelect, { id: 'dos-check-d', value: target, onChange: setTarget, dialects }),
      jsx(Button, { size: 'sm', disabled: busy || !source.trim() || !translated.trim(), onClick: run, children: busy ? 'Checking…' : 'Check' })] }),
    res ? jsx(Verdict, { check: res }) : null
  ] })
}

function ByDialect({ ledger, names }) {
  const rows = (ledger?.by_dialect || []).filter(r => r.dialect !== '-' && r.dialect !== '?').slice(0, 10)
  return jsxs('section', { className: 'dos-card', 'aria-labelledby': 'dos-by', children: [
    jsxs('div', { children: [jsx('h2', { id: 'dos-by', className: 'dos-label', children: 'Checks by dialect' }),
      jsx('p', { className: 'dos-sub', children: 'From the QA ledger: verdicts only, never your text.' })] }),
    !ledger ? jsx(Skeleton, { style: { height: 90, borderRadius: 6 } })
      : !rows.length ? jsx(EmptyState, { title: 'No checks yet', description: 'Checks the agent or this page runs show up here, per dialect.' })
      : jsx('div', { children: rows.map(r => jsxs('div', { className: 'dos-sum', children: [
          jsxs('span', { children: [jsx('span', { className: 'dos-code', children: r.dialect }), names[r.dialect] ? jsx('span', { className: 'dos-why', children: ` ${names[r.dialect].replace(/ Spanish$/, '')}` }) : null] }),
          jsxs('span', { className: 'dos-bar', role: 'img', 'aria-label': `${r.passed} passed, ${r.blocked} did not`, children: [
            jsx('i', { style: { width: `${r.checked ? (r.passed / r.checked) * 100 : 0}%`, background: 'var(--dos-pass)' } }),
            jsx('i', { style: { width: `${r.checked ? (r.blocked / r.checked) * 100 : 0}%`, background: 'var(--dos-block)' } })] }),
          jsx('span', { className: 'dos-num', children: r.checked ? `${r.passed} of ${r.checked} passed` : `${r.calls} call${r.calls === 1 ? '' : 's'}` })
        ] }, r.dialect)) })
  ] })
}

function Recent({ ledger }) {
  const rows = (ledger?.rows || []).slice(0, 10)
  const verdict = r => r.tool !== 'dialectos_validate' ? (r.ok ? 'done' : 'failed')
    : r.passed === true ? 'passed' : `${r.blocking_issue_count || 0} blocking`
  return jsxs('section', { className: 'dos-card', 'aria-labelledby': 'dos-recent', children: [
    jsxs('div', { children: [jsx('h2', { id: 'dos-recent', className: 'dos-label', children: 'Recent' }),
      jsx('p', { className: 'dos-sub', children: ledger ? `${ledger.total} recorded calls` : ' ' })] }),
    !ledger ? jsx(Skeleton, { style: { height: 90, borderRadius: 6 } })
      : !rows.length ? jsx(EmptyState, { title: 'Nothing yet', description: 'Ask the agent for Spanish, or use the tools above.' })
      : jsx('div', { children: rows.map((r, n) => jsxs('div', { className: 'dos-ev', children: [
          jsx('span', { children: ago(r.ts) }),
          jsx('span', { children: `${TOOL_NAMES[r.tool] || r.tool}${r.via === 'page' ? ' · page' : ''}` }),
          jsx('span', { className: 'dos-code', children: r.dialect && r.dialect !== '-' ? r.dialect : '' }),
          jsx('span', { style: { color: r.tool === 'dialectos_validate' ? (r.passed === true ? 'var(--dos-pass)' : 'var(--dos-block)') : undefined }, children: verdict(r) })
        ] }, n)) })
  ] })
}

function Dialects({ dialects, target, setTarget, defaultDialect, failed }) {
  return jsxs('section', { className: 'dos-card', 'aria-labelledby': 'dos-list', children: [
    jsxs('div', { children: [jsx('h2', { id: 'dos-list', className: 'dos-label', children: `${dialects.length || 25} variants` }),
      jsx('p', { className: 'dos-sub', children: 'Pick one to translate or check into.' })] }),
    failed ? jsx(ErrorState, { title: 'Could not load the variants', description: failed })
      : !dialects.length ? jsx(Skeleton, { style: { height: 120, borderRadius: 6 } })
      : jsx('div', { className: 'dos-grid', children: dialects.map(d => jsxs('button', { className: 'dos-chip', 'aria-pressed': d.code === target, onClick: () => setTarget(d.code), children: [
          jsx('span', { className: 'dos-code', children: d.code }), jsx('span', { children: d.name.replace(/ Spanish$/, '') }),
          d.code === defaultDialect ? jsx('small', { children: 'default' }) : null] }, d.code)) })
  ] })
}

function DialectosPage({ ctx }) {
  const qc = useQueryClient()
  const status = useQuery({ queryKey: [ID, 'status'], queryFn: () => ctx.rest('/status') })
  const list = useQuery({ queryKey: [ID, 'dialects'], queryFn: () => ctx.rest('/dialects'), staleTime: Infinity })
  const ledger = useQuery({ queryKey: [ID, 'ledger'], queryFn: () => ctx.rest('/ledger?limit=40'), refetchInterval: 30_000 })
  const s = status.data
  const dialects = list.data?.ok ? list.data.data : []
  const names = Object.fromEntries(dialects.map(d => [d.code, d.name]))
  const [picked, setTarget] = useState(null)
  const target = picked || s?.default_dialect || 'es-MX'
  const refresh = () => { qc.invalidateQueries?.({ queryKey: [ID, 'ledger'] }); ledger.refetch?.() }
  const shared = { ctx, status: s, dialects, target, setTarget, refresh }
  return jsx('div', { className: 'dos-host', children: jsxs('div', { className: 'dos', children: [
    jsxs('header', { className: 'dos-head', children: [
      MARK ? jsx('img', { src: `data:image/webp;base64,${MARK}`, alt: '' }) : jsx('span', {}),
      jsx('h1', { className: 'dos-title', children: 'DialectOS' }),
      jsx('p', { className: 'dos-tag', children: 'Spanish for the region you mean, checked before you send it.' })
    ] }),
    status.isError ? jsx(ErrorState, { title: 'DialectOS backend unavailable', description: 'Turn on the DialectOS plugin, then reopen this page.' })
      : jsxs('div', { className: 'dos-facts', children: [
        jsxs('span', { className: 'dos-fact', children: ['CLI ', jsx('b', { children: s ? (s.cli === 'release' ? `v${s.cli_version} release` : 'custom build') : '…' })] }),
        jsxs('span', { className: 'dos-fact', 'data-off': s && !s.provider ? '' : undefined, children: ['Provider ', jsx('b', { children: s ? (s.provider ? PROVIDER_NAMES[s.provider] : 'none, translate off') : '…' })] }),
        jsxs('span', { className: 'dos-fact', children: ['Default ', jsx('b', { children: s?.default_dialect || '…' })] }),
        jsxs('span', { className: 'dos-fact', children: ['Spanish brief ', jsx('b', { children: s ? (s.inject_on_spanish ? 'on' : 'off') : '…' })] }),
        s && !s.runner_found ? jsx('span', { className: 'dos-fact', 'data-off': '', children: jsx('b', { children: 'Node/npx not found' }) }) : null
      ] }),
    jsxs('p', { className: 'dos-note', children: [jsx('b', { children: 'Checks are advisory.' }), ' A translation can pass with its meaning changed, such as a flipped negation or the wrong sense of a word. Read it before you use it.'] }),
    jsxs('div', { className: 'dos-cols', children: [jsx(TryIt, shared), jsx(CheckPair, shared)] }),
    jsxs('div', { className: 'dos-cols', children: [jsx(ByDialect, { ledger: ledger.data, names }), jsx(Recent, { ledger: ledger.data })] }),
    jsx(Dialects, { dialects, target, setTarget, defaultDialect: s?.default_dialect, failed: list.data && !list.data.ok ? list.data.error : null })
  ] }) })
}

export default {
  id: ID,
  name: 'DialectOS',
  register(ctx) {
    const style = document.createElement('style')
    style.dataset.plugin = ID
    style.textContent = CSS
    document.head.appendChild(style)
    ctx.onDispose(() => style.remove())
    ctx.registerMany([
      { id: 'page', area: ROUTES_AREA, data: { path: PATH }, render: () => jsx(DialectosPage, { ctx }) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: PATH, label: 'DialectOS', codicon: 'globe' } },
      { id: 'open', area: PALETTE_AREA, data: { id: 'dialectos.open', label: 'DialectOS: open', keywords: ['spanish', 'dialect', 'translate', 'localize', 'es-MX'], run: () => host.navigate(PATH) } }
    ])
  }
}
